import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Page.css";

function Jobs() {
  const [jobs, setJobs] = useState([]);
  const [selectedYear, setSelectedYear] = useState(""); 
  const [selectedBranch, setSelectedBranch] = useState("");
  const [loading, setLoading] = useState(false);

  // Initial Fetch: Load all "Job" types (Full-Time)
  useEffect(() => {
    fetchJobs();
  }, []);

  const fetchJobs = async () => {
    setLoading(true);
    try {
      // Fetching all jobs; we will filter for "Job" type locally or via query
      const response = await axios.get("http://localhost:5000/api/jobs");
      
      // Filtering for Full-time "Job" types from your scraper
      const fullTimeJobs = response.data.filter(j => j.jobType === "Job");
      setJobs(fullTimeJobs);
    } catch (err) {
      console.error("Error fetching jobs:", err);
    }
    setLoading(false);
  };

  // Local UI Filtering logic to match the new JSON structure
  const filteredJobs = jobs.filter(job => {
    // Check if the selected branch is inside the job's branch array
    const matchesBranch = selectedBranch === "" || job.branch?.includes(selectedBranch);
    
    // Check if the selected year (e.g., "4th") is in the eligibleYear array
    const matchesYear = selectedYear === "" || job.eligibleYear?.includes(selectedYear);

    return matchesBranch && matchesYear;
  });

  return (
    <div className="page">
      <header className="page-header">
        <h1>Full-Time Career Opportunities</h1>
        <p>Verified job openings for freshers and graduating engineering students</p>
      </header>

      {/* Filters Bar */}
      <div className="filters-bar">
        <div className="filter-item">
          <label>Target Eligibility</label>
          <select value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
            <option value="">All Candidates</option>
            <option value="4th">4th Year / Graduates</option>
          </select>
        </div>

        <div className="filter-item">
          <label>Branch</label>
          <select value={selectedBranch} onChange={(e) => setSelectedBranch(e.target.value)}>
            <option value="">All Branches</option>
            <option value="CSE/IT">CSE / IT</option>
            <option value="ECE">ECE</option>
            <option value="EEE">EEE</option>
            <option value="Mechanical">Mechanical</option>
            <option value="Civil">Civil</option>
          </select>
        </div>

        <button className="btn-search" onClick={fetchJobs} disabled={loading}>
          {loading ? "Refreshing..." : "Sync Database"}
        </button>
      </div>

      {/* Jobs Grid */}
      <div className="jobs-grid">
        {!loading && filteredJobs.length > 0 ? (
          filteredJobs.map((job) => (
            <div className="job-card" key={job._id}>
              {/* If you add a category field later for PSU, the logic remains here */}
              {job.source === 'Government' && <span className="govt-badge">Official PSU</span>}
              
              <div className="card-body">
                <div className="card-top">
                  <span className="type-badge job-type">Full-Time</span>
                  <span className="source-tag">{job.source}</span>
                </div>

                <h3 className="job-title">{job.jobTitle}</h3>
                <h4 className="company-name">{job.companyName}</h4>
                
                <div className="job-meta">
                  <span>📍 {job.location || "Multiple Locations"}</span>
                </div>


                {job.skills?.length > 0 && (
                  <div className="skills-section">
                    <strong>Required:</strong> {job.skills.join(", ")}
                  </div>
                )}
              </div>

              <div className="card-footer">
                <span className="scraped-date">
                  Updated: {new Date(job.syncedAt).toLocaleDateString()}
                </span>
                <a 
                  href={job.applicationLink} 
                  target="_blank" 
                  rel="noreferrer" 
                  className="apply-link"
                >
                  Apply Now
                </a>
              </div>
            </div>
          ))
        ) : (
          !loading && (
            <div className="empty-state">
              No full-time roles found. Try refreshing or changing filters.
            </div>
          )
        )}
      </div>
      {loading && <div className="loader">Accessing CareerHub Database...</div>}
    </div>
  );
}

export default Jobs;
